#!/usr/bin/env python3

import os

def cleanup_bash_history():
    """Remove .bash_history files from /home and /root directories"""
    # Directories to search
    search_paths = ['/home', '/root']

    # Counter for removed files
    removed_count = 0

    # Traverse each search path
    for base_path in search_paths:
        if os.path.exists(base_path):
            for root, dirs, files in os.walk(base_path):
                for file in files:
                    if file == '.bash_history':
                        file_path = os.path.join(root, file)
                        try:
                            os.remove(file_path)
                            print(f"Removed: {file_path}")
                            removed_count += 1
                        except PermissionError:
                            print(f"Permission denied: {file_path}")
                        except Exception as e:
                            print(f"Error removing {file_path}: {e}")

    print(f"Total .bash_history files removed: {removed_count}")

if __name__ == "__main__":
    cleanup_bash_history()
```

